cd /root && python3 -c "
import random, string
def rand_line(n):
    return ''.join(random.choice(string.ascii_letters+string.digits+string.punctuation) for _ in range(n))
with open('system_logs.txt','w') as f:
    for i in range(50):
        if random.random() < 0.3:
            f.write('\n')
        else:
            f.write(rand_line(random.randint(5,80))+'\n')
"
wc -l system_logs.txt
